<script setup lang="ts">
definePageMeta({ middleware:'teacher' }); const route=useRoute(); const supabase=useSupabaseClient(); const event=ref<any>(null); const participants=ref<any[]>([]); const message=ref('')
const load=async()=>{const {data:e}=await supabase.from('events').select('*,sport:sports(name,measurement_type)').eq('id',route.params.id).single();event.value=e;const {data:p}=await supabase.from('event_participants').select('id,lane,bib_number,student:profiles(id,first_name,last_name,house:houses(name)),result:results(id,result_value,result_display,position,points,status)').eq('event_id',route.params.id).order('lane');participants.value=(p||[]).map((x:any)=>({...x,input:x.result?.[0]?.result_value??''}))}
const save=async()=>{message.value=''; for(const p of participants.value){ if(p.input===''||p.input===null)continue; await supabase.from('results').upsert({event_id:Number(route.params.id),student_id:p.student.id,result_value:Number(p.input),result_display:String(p.input),status:'official'},{onConflict:'event_id,student_id'}) } await supabase.rpc('rank_event_results',{p_event_id:Number(route.params.id)}); message.value='Results saved and ranked.'; await load() }
onMounted(load)
</script>
<template><main class="mx-auto max-w-5xl px-4 py-8"><NuxtLink to="/teacher" class="text-sm font-semibold text-blue-600">← Teacher Events</NuxtLink><div v-if="event"><h1 class="mt-3 text-3xl font-bold">{{event.name}}</h1><p class="mt-2 text-slate-500">{{event.sport?.name}} · {{event.event_date}} · {{event.location}}</p><div v-if="message" class="mt-5 rounded-lg bg-green-50 p-3 text-green-700">{{message}}</div><div class="mt-6 overflow-hidden rounded-xl border bg-white"><table class="w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Lane</th><th>Student</th><th>House</th><th>Result</th><th>Place</th><th>Points</th></tr></thead><tbody><tr v-for="p in participants" :key="p.id" class="border-t"><td class="p-4">{{p.lane||'—'}}</td><td class="font-semibold">{{p.student.first_name}} {{p.student.last_name}}</td><td>{{p.student.house?.name||'—'}}</td><td><input v-model="p.input" type="number" step="0.001" class="w-28 rounded border px-3 py-2"></td><td>{{p.result?.[0]?.position||'—'}}</td><td>{{p.result?.[0]?.points||0}}</td></tr><tr v-if="!participants.length"><td colspan="6" class="p-8 text-center text-slate-500">No students have been added to this event yet.</td></tr></tbody></table></div><button class="mt-5 rounded-lg bg-emerald-600 px-5 py-3 font-semibold text-white" @click="save">Save & Rank Results</button></div></main></template>
